use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=src/client/notes.rs");

    let mut generated = String::from(
        "// AUTO-GENERATED by build.rs. Do not edit this file manually.\n\
         use crate::mi_api_types::notes;\n\nimpl super::Client {\n",
    );
    for (path, method_name, empty_response) in ENDPOINTS {
        let module_path = path
            .strip_prefix("/notes/")
            .expect("notes endpoint path")
            .split('/')
            .map(|segment| segment.replace('-', "_"))
            .collect::<Vec<_>>()
            .join("::");
        let helper = if *empty_response {
            "http_api_empty"
        } else {
            "http_api"
        };
        generated.push_str(&format!(
            "    pub async fn {method_name}(\n        &self,\n        request: notes::{module_path}::Request,\n    ) -> anyhow::Result<notes::{module_path}::Response> {{\n        self.{helper}(\"{path}\", &request).await\n    }}\n\n"
        ));
    }
    generated.push_str("}\n");

    let output = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("manifest dir is set"))
        .join("src/client/notes.rs");
    let current = fs::read_to_string(&output).unwrap_or_default();
    if current != generated {
        fs::write(output, generated).expect("write generated notes Client methods");
    }
}

const ENDPOINTS: &[(&str, &str, bool)] = &[
    ("/notes/children", "get_note_children", false),
    ("/notes/clips", "get_note_clips", false),
    ("/notes/conversation", "get_note_conversation", false),
    ("/notes/create", "create_note", false),
    ("/notes/delete", "delete_note", true),
    ("/notes/drafts/count", "count_note_drafts", false),
    ("/notes/drafts/create", "create_note_draft", false),
    ("/notes/drafts/delete", "delete_note_draft", true),
    ("/notes/drafts/list", "list_note_drafts", false),
    ("/notes/drafts/update", "update_note_draft", false),
    ("/notes/favorites/create", "favorite_note", true),
    ("/notes/favorites/delete", "unfavorite_note", true),
    ("/notes/featured", "get_featured_notes", false),
    ("/notes/global-timeline", "global_timeline", false),
    ("/notes/hybrid-timeline", "hybrid_timeline", false),
    ("/notes/local-timeline", "local_timeline", false),
    ("/notes/mentions", "get_note_mentions", false),
    ("/notes/polls/recommendation", "recommend_note_polls", false),
    ("/notes/polls/vote", "vote_on_note_poll", true),
    ("/notes/reactions", "get_note_reactions", false),
    ("/notes/reactions/create", "create_note_reaction", true),
    ("/notes/reactions/delete", "delete_note_reaction", true),
    ("/notes/renotes", "get_note_renotes", false),
    ("/notes/replies", "get_note_replies", false),
    ("/notes/search", "search_notes", false),
    ("/notes/search-by-tag", "search_notes_by_tag", false),
    ("/notes/show", "show_note", false),
    ("/notes/show-partial-bulk", "show_notes_partial_bulk", false),
    ("/notes/state", "get_note_state", false),
    ("/notes/thread-muting/create", "mute_note_thread", true),
    ("/notes/thread-muting/delete", "unmute_note_thread", true),
    ("/notes/timeline", "timeline", false),
    ("/notes/translate", "translate_note", false),
    ("/notes/unrenote", "unrenote", true),
    ("/notes/user-list-timeline", "user_list_timeline", false),
];
